<?php $done=ready() && (int)Db::scalar("SELECT COUNT(*) FROM users WHERE role='super_admin'")>0; ?>
<section class="auth-section auth-centered container"><div class="form-card auth-card"><div class="eyebrow">HASAD / <?= t('إعداد أول مرة','FIRST-TIME SETUP') ?></div><h1><?= t('نجهّز البداية.','Let’s set things up.') ?></h1><?php if($done): ?><p><?= t('تم إعداد حساب المدير بالفعل.','The initial administrator account is already configured.') ?></p><a class="button button-green" href="<?= e(url('admin-login')) ?>"><?= t('دخول الإدارة','Team sign in') ?></a><?php elseif(!ready()): ?><p><?= t('انسخ config.example.php إلى config.php، واضبط بيانات MySQL، واستورد database/schema.sql من phpMyAdmin. ثم افتح هذه الصفحة عبر HTTPS.','Copy config.example.php to config.php, enter your MySQL settings, and import database/schema.sql with phpMyAdmin. Then open this page over HTTPS.') ?></p><p class="caption"><?= t('خطوات تفصيلية موجودة في دليل التثبيت المرفق بالمشروع.','Detailed steps are provided in the project installation guide.') ?></p><?php else: ?><form method="post" action="<?= e(url('setup')) ?>"><?= csrf_field() ?><input type="hidden" name="action" value="setup-admin"><?php field(t('رمز الإعداد من ملف config.php','Setup token from config.php'),'setup_token','password','','required autocomplete="off"');field(t('اسم مدير النظام','Super admin name'),'name','text','','required maxlength="160"');field(t('بريد الإدارة','Admin email'),'email','email','','required maxlength="190" dir="ltr"');field(t('كلمة المرور — ١٢ حرفاً على الأقل','Password — at least 12 characters'),'password','password','','required minlength="12" autocomplete="new-password"'); ?><button class="button button-green button-full"><?= t('إنشاء المدير الأول','Create initial administrator') ?></button></form><?php endif; ?></div></section>
